// ===== CONFIGURAÇÃO =====
const OWNER = '5581999999999@c.us';      // quem recebe os lembretes
const OFFSETS = [1440, 60, 15];          // minutos antes: 24h, 1h, 15min (configurável)
const GRACE = 5;                          // tolerância (min) caso o agendador atrase
const TZ = 'America/Recife';
// ========================
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const now = Date.now();
for (const k of Object.keys(sd.sent)) if (now - sd.sent[k] > 3 * 24 * 3600 * 1000) delete sd.sent[k];

const kind = (t) => {
  t = (t || '').toLowerCase();
  if (/entrevista/.test(t)) return ['Entrevista', '🎯'];
  if (/viagem|voo|vôo|hotel|aeroporto/.test(t)) return ['Viagem', '✈️'];
  if (/estudo|aula|prova|curso|estudar/.test(t)) return ['Estudo', '📚'];
  if (/reuni|call|meeting|alinhamento/.test(t)) return ['Reunião', '👥'];
  return ['Compromisso', '📌'];
};
const label = (off) => off >= 1440 ? `${Math.round(off/1440)} dia(s)` : off >= 60 ? `${Math.round(off/60)} hora(s)` : `${off} minutos`;

const out = [];
for (const it of $input.all()) {
  const e = it.json;
  if (!e || e.status === 'cancelled') continue;
  const raw = typeof e.start === 'string' ? e.start : (e.start && e.start.dateTime);
  if (!raw) continue;                                   // ignora eventos de dia inteiro
  const start = new Date(raw).getTime();
  if (isNaN(start)) continue;
  const minsLeft = (start - now) / 60000;
  for (const off of OFFSETS) {
    const key = `${e.id}|${raw}|${off}`;                // inclui o horário: se mudar, é um lembrete novo
    if (sd.sent[key]) continue;
    if (minsLeft > 0 && minsLeft <= off && minsLeft > off - GRACE) {
      const d = new Date(start);
      const hora = d.toLocaleTimeString('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });
      const dia = d.toLocaleDateString('pt-BR', { timeZone: TZ, weekday: 'short', day: '2-digit', month: '2-digit' });
      const [tipo, emoji] = kind(e.summary);
      let text = `${emoji} *${tipo}* em ${label(off)}\n*${e.summary || '(sem título)'}*\n🗓 ${dia} às ${hora}`;
      if (e.location) text += `\n📍 ${e.location}`;
      if (e.description) text += `\n📝 ${String(e.description).slice(0, 200)}`;
      out.push({ json: { chatId: OWNER, text, key } });
    }
  }
}
return out;

// Só marca como enviado se o envio deu certo (se falhar, tenta de novo no próximo minuto)
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const src = $('Calcular lembretes devidos').all();
$input.all().forEach((it, i) => {
  if (!it.json.error && src[i]) sd.sent[src[i].json.key] = Date.now();
});
return [];
